let projects=structuredClone(initialProjects),variant,web,filter='all',checking=false,run=0,dialogProject=null,diffFile='index.html',diffLayout='split',diffDirection='incoming',note='',state=new URLSearchParams(location.search).get('state')||'launch';let dialogMode='';const smallScreen=matchMedia('(max-width:56rem)');
