function boot(n){variant=n;web=n===3;document.body.classList.toggle('web',web);if(state==='long')projects[0].name='Studio archive — international exhibition documentation and research collection';projects.forEach(p=>{p.phase='queued';p.checked=null;});document.addEventListener('click',click);document.addEventListener('change',change);document.addEventListener('input',e=>{if(e.target.id==='note')note=e.target.value;if(e.target.id==='keyword'){keyword=e.target.value;paintList();}});smallScreen.addEventListener('change',()=>{if(dialogMode==='diff')paintDiff()});if(state==='empty'){projects=[];render();}else if(state==='ready'||state==='long'||state==='offline'){projects.forEach(p=>{p.phase=state==='offline'||p.kind==='error'?'error':'done';p.checked=p.phase==='done'?'Just now':null});render();}else if(state==='checking'||state==='partial'){checking=true;if(state==='partial'){projects[0].phase='done';projects[1].phase='done';projects[0].checked=projects[1].checked='Just now';projects[2].phase='checking';}else projects[0].phase='checking';render();}else checkAll();}
function appearanceControls(){return `<div class="appearance"><label>${icon('palette')}<select aria-label="Color palette" data-appearance="palette"><option value="default">Default</option><option value="ink">Ink</option><option value="quiet">Quiet</option></select></label><label>${icon('sun')}<select aria-label="Appearance" data-appearance="theme"><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></label>${button('Account','account','user')}</div>`;}
