function r3Render(){document.title=`zudo-ez-host · ${web?'Web projects':'Independent projects'}`;document.querySelector('#app').innerHTML=`<div class="lab"><a class="inline" href="index.html">${icon('back')}Round 3 gallery</a><span class="tag">${web?'03 / WEB · CLOUD RECORDS':variant===1?'01 / DESKTOP · PROJECT LIST':'02 / DESKTOP · PROJECT CARDS'}</span><span class="grow"></span><small>Simulated data and transfers</small></div><header class="topbar"><span class="brand inline">${icon('folder')}ZUDO-EZ-HOST</span><span class="mode">${icon(web?'window':'computer')}${web?'Web app':'Tauri app'}</span>${appearanceControls()}</header><main class="page"><div class="pagehead"><div><h1>Projects</h1><div class="subtitle">${web?'Saved checkpoints and published sites.':'Each folder is an independent project.'}</div></div>${button(web?'Refresh':checking?'Restart check':'Check again','check','refresh')}</div><section id="checking-status" aria-live="polite"></section><div class="filterbar">${button('All projects','filter:all','folder','',`aria-pressed="${filter==='all'}"`)}${!web?button('Remote updates','filter:remote','down','',`aria-pressed="${filter==='remote'}"`):''}<small>${web?'Read-only · no access to local folders':'MacBook · checks run automatically on launch'}</small></div><section id="projects" class="project-list ${variant===2?'cards':''}" aria-label="Projects"></section><p class="footnote">${web?'Compare history and view account information here. Use the desktop app or CLI for file operations.':'Checking compares state only. Files move only when you choose Pull or Push.'}</p></main><dialog class="review-dialog" id="dialog" aria-labelledby="dialog-title"></dialog><div id="toast" role="status"></div>`;appearance.apply();renderRows();}
function r3RenderRows(){const checkButton=document.querySelector('[data-action="check"]');if(checkButton){checkButton.innerHTML=icon('refresh')+(web?'Refresh':checking?'Restart check':'Check again');checkButton.disabled=projects.some(p=>p.phase==='rechecking');}const done=projects.filter(p=>p.phase==='done'||p.phase==='error').length;const errors=projects.filter(p=>p.phase==='error').length;const safe=projects.filter(p=>p.phase==='done'&&p.kind==='remote');let title=checking?(web?'Loading your projects…':'Checking your projects…'):projects.length===0?'No projects connected':errors?(web?'Loaded with unavailable records':'Check finished · some projects unavailable'):(web?'Cloud records loaded':'Check complete');let sub=checking?`${done} of ${projects.length} ${web?'loaded':'checked'} · ${web?'Reading cloud records.':'No files are being transferred.'}`:projects.length===0?(web?'Connect a folder using the desktop app or CLI.':'Connect a folder to begin.'):`${projects.length-errors} ${web?'loaded':'checked'}${errors?` · ${errors} unavailable`:''}${web?'':` · ${safe.length} safe to pull`} · Just now`;
document.querySelector('#checking-status').innerHTML=`<div class="check-banner">${checking?spin():icon(errors?'alert':projects.length?'check':'folder')}<div class="summary"><h2>${title}</h2><p>${sub}</p>${checking?`<div class="check-progress" role="progressbar" aria-label="${web?'Loading projects':'Checking projects'}" aria-valuemin="0" aria-valuemax="${projects.length}" aria-valuenow="${done}"><span style="width:${projects.length?done/projects.length*100:0}%"></span></div>`:''}</div><div class="actions">${!web&&projects.length?button('Pull all…','pull-all','down','primary',`data-write ${checking||projects.some(p=>p.phase==='rechecking')||!safe.length?'disabled':''}`):''}${errors&&!checking?button('Retry unavailable','retry-all','refresh'):''}</div></div>`;
const shown=projects.filter(p=>filter!=='remote'||p.phase==='done'&&p.kind==='remote');document.querySelector('#projects').innerHTML=projects.length===0?`<div class="empty">${icon('folder')}<strong>No projects yet</strong><p>${web?'Cloud projects appear after the first push.':'Your connected folders will appear here.'}</p>${button('Load sample projects','samples','folder')}</div>`:shown.length===0?'<div class="empty"><strong>No verified remote updates</strong><p>Only successfully checked projects appear in this filter.</p></div>':`${variant!==2?`<div class="list-head label"><span>Project</span><span>${web?'Cloud checkpoint':'Current state'}</span><span>Actions</span></div>`:''}${shown.map(p=>{const s=statusOf(p);let actions=p.phase==='error'?button('Retry','retry:'+p.id,'refresh'):p.phase!=='done'?button(web?'Loading…':'Checking…','noop','refresh','','disabled'):web?button('History','history:'+p.id,'history'):p.kind==='remote'?button('Review & pull','incoming:'+p.id,'down','','data-write'):p.kind==='local'?button('Review changes','local:'+p.id,'diff'):p.kind==='conflict'?button('Compare','conflict:'+p.id,'diff'):button('History','history:'+p.id,'history');return `<article class="project ${p.phase==='checking'?'checking-row':''}" data-project="${p.id}"><div class="identity-cell"><h2>${icon('folder')}${esc(p.name)}</h2>${!web?`<span class="path">${esc(p.path)}</span>`:''}<span class="live-line">${icon('window')}${p.phase==='done'?`Live ${p.live}`:'Live state not verified'}</span></div><div class="status-meta"><span class="status ${s.tone}">${s.i==='spinner'?spin():icon(s.i)}${s.label}</span><span class="substatus">${s.detail}</span>${p.phase==='done'?`<span class="substatus">${web?'Loaded':'Checked'} ${p.checked||'just now'}</span>`:''}</div><div class="project-actions">${actions}${p.phase==='done'&&!web?ib('Project details: '+p.name,'details:'+p.id,'settings'):''}</div></article>`}).join('')}`;}
async function checkAll(){const token=++run;checking=true;projects.forEach(p=>p.phase='queued');render();for(const p of projects){if(token!==run)return;p.phase='checking';renderRows();await delay(950);if(token!==run)return;p.phase=state==='offline'||p.kind==='error'?'error':'done';if(p.phase==='done')p.checked='just now';renderRows();}checking=false;renderRows();}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
