async function pull(ids){document.querySelector('#dialog').close();const selected=projects.filter(p=>ids.includes(p.id)&&p.phase==='done'&&p.kind==='remote');selected.forEach(p=>p.phase='rechecking');renderRows();await delay(1100);selected.forEach(p=>{p.kind='same';p.phase='done';p.local=p.cloud;p.checked='just now';});renderRows();toast(selected.map(p=>p.name).join(', ')+' updated. Other projects and live sites unchanged.');}
