function previousClick(e){const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;const [verb,id]=action.split(':');const p=projects.find(p=>p.id===id);const writeVerbs=['incoming','pull-all','confirm-pull','confirm-pull-all','push','confirm-push','publish','confirm-publish','resolve-local','resolve-remote','confirm-replace','restore','confirm-restore'];if(writeVerbs.includes(verb)&&(web||state==='offline'))return;
if(verb==='check'){document.querySelector('#dialog')?.close();checkAll();return;}if(verb==='filter'){filter=id;renderRows();document.querySelectorAll('[data-action^="filter:"]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.action==='filter:'+filter)));return;}if(verb==='retry'){retry([id]);return;}if(verb==='retry-all'){retry(projects.filter(p=>p.phase==='error').map(p=>p.id));return;}if(verb==='close'){document.querySelector('#dialog').close();dialogMode='';return;}if(verb==='dismiss'){document.querySelector('#toast').innerHTML='';return;}if(verb==='samples'){location.search='';return;}if(verb==='details'){details(p);return;}if(['incoming','local','conflict','history-diff'].includes(verb)){openDiff(p,verb==='history-diff'?'history':verb);return;}if(verb==='history'){historyView(p);return;}if(verb==='layout'){diffLayout=id;paintDiff();return;}if(verb==='pull-all'){pullAll();return;}if(verb==='confirm-pull'){pull([id]);return;}if(verb==='confirm-pull-all'){pull(projects.filter(p=>p.phase==='done'&&p.kind==='remote').map(p=>p.id));return;}if(verb==='account'){modal('Account',`<div class="detail-row"><span>User</span><b>Alex Morgan</b></div><div class="detail-row"><span>Email</span><span>alex@example.test</span></div><div class="detail-row"><span>Devices</span><span>MacBook · Studio Mac · WSL PC · Linux</span></div><p class="footnote">CLI and MCP work on macOS, WSL and Linux independently of the desktop app.</p>`,button('Close','close','close'),'Read-only user and device information');return;}if(verb==='push'){modal(p.name,`<p>Save these ${p.files} local file changes as a new cloud checkpoint.</p><p><b>${esc(note||'Local update')}</b></p><p class="muted">Recheck the cloud revision before saving. The live site stays on ${p.live}.</p>`,button('Cancel','close','close')+button('Push checkpoint','confirm-push:'+id,'up','primary','data-write'),'Explicit push · only this project');return;}if(verb==='confirm-push'){p.cloud='C'+String(Number(p.cloud.slice(1))+1).padStart(2,'0');p.local=p.cloud;p.kind='same';document.querySelector('#dialog').close();renderRows();toast(p.name+' saved to '+p.cloud+'. Publication unchanged.');return;}if(verb==='publish'){modal(p.name,`<p>Publish the complete ${p.cloud} checkpoint to this project’s site.</p><p>Current live version: ${p.live}. Other projects are unaffected.</p>`,button('Cancel','close','close')+button('Publish '+p.cloud,'confirm-publish:'+id,'window','primary','data-write'),'Explicit publication');return;}if(verb==='confirm-publish'){p.live=p.cloud;document.querySelector('#dialog').close();renderRows();toast(p.name+' published.');return;}if(verb==='resolve-local'||verb==='resolve-remote'){modal(p.name,`<p>${verb==='resolve-local'?'Keep local files and replace the remote checkpoint. Preserve the previous cloud checkpoint in history.':'Preserve local edits in a recovery copy, then replace this folder with the reviewed remote checkpoint.'}</p><p>Recheck both versions before proceeding. Publication does not change.</p>`,button('Cancel','close','close')+button('Preserve and replace','confirm-replace:'+id,'history','primary','data-write'),'Resolve only this project');return;}if(verb==='confirm-replace'){document.querySelector('#dialog').close();toast('Replacement preview accepted in this mock. No real files were changed.');return;}if(verb==='restore'){modal(p.name,'<p>Restore the previous file set into a new checkpoint for this project. Preserve all existing history.</p><p>Review file replacements and deletions before implementation applies a real restore. Local folders and publication stay unchanged.</p>',button('Cancel','close','close')+button('Create restored checkpoint','confirm-restore:'+id,'history','primary','data-write'),'Project recovery');return;}if(verb==='confirm-restore'){document.querySelector('#dialog').close();toast('Restore simulated for '+p.name+'. No local files or publication changed.');}}
