const propertyDefs={status:['Status','minmax(150px,1fr)'],published:['Published','115px'],path:['Local folder','minmax(170px,1fr)'],cloud:['Saved','70px'],live:['Live','70px'],device:['Updated by','120px']};
let shownProps=null;
function props(){if(shownProps)return shownProps;try{const saved=JSON.parse(localStorage.getItem('zudo-ez-host-list-'+(web?'web':'desktop'))||'null');shownProps=Array.isArray(saved)?saved.filter(x=>x in propertyDefs&&(!web||x!=='path')):['status','published'];}catch{shownProps=['status','published'];}return shownProps;}
function saveProps(){try{localStorage.setItem('zudo-ez-host-list-'+(web?'web':'desktop'),JSON.stringify(props()))}catch{}}
function shortStatus(p){if(p.phase==='uploading')return {label:'Pushing & publishing…',i:'spinner',tone:''};const s=statusOf(p);s.label=s.label.replace('Remote updates available','Remote updates').replace('Latest checkpoint is live','Published').replace('Newer checkpoint saved','Saved, not published').replace('Checking local and remote…','Checking…').replace('Waiting to check','Waiting…').replace('Loading cloud records…','Loading…');return s;}
function statusHTML(p){const s=shortStatus(p);return `<span class="inline ${s.tone}">${s.i==='spinner'?spin():icon(s.i)}${s.label}</span>`;}
function render(){document.title='zudo-ez-host · '+(currentProject?'Project detail':'Projects');document.querySelector('#app').innerHTML=`<div class="lab"><a class="inline" href="index.html">${icon('back')}Round 6</a><span class="tag">${web?'WEB · READ ONLY':'DESKTOP'}</span><span class="grow"></span><small>Prototype · simulated operations</small></div><header class="topbar"><span class="brand inline">${icon('folder')}ZUDO-EZ-HOST</span><span class="mode">${icon(web?'window':'computer')}${web?'Web':'Desktop'}</span>${appearanceControls()}</header><main class="page" id="page-content"></main><dialog class="review-dialog" id="dialog" aria-labelledby="dialog-title"></dialog><div id="toast" role="status"></div>`;appearance.apply();renderRows();}
function renderRows(){if(currentProject){paintDetail();return;}if(document.querySelector('#simple-list')){paintStatus();paintList();const input=document.querySelector('#keyword');if(input&&input.value!==keyword)input.value=keyword;document.querySelectorAll('[data-prop]').forEach(el=>el.checked=props().includes(el.dataset.prop));return;}document.querySelector('#page-content').innerHTML=`<div class="pagehead"><h1>Projects</h1><div id="compact-status" class="compact-status" aria-live="polite"></div></div><div class="list-tools"><label class="keyword">${icon('search' in glyphs?'search':'folder')}<input id="keyword" aria-label="Filter projects" placeholder="${web?'Filter projects…':'Filter by project or folder…'}" value="${esc(keyword)}"></label><div class="display-wrap">${button('Display','display','settings','',`aria-expanded="${displayOpen}" aria-controls="display-menu"`)}<div id="display-menu" class="display-menu" ${displayOpen?'':'hidden'}><div class="label">Show in list</div>${Object.entries(propertyDefs).filter(([k])=>!web||k!=='path').map(([key,[label]])=>`<label><input type="checkbox" data-prop="${key}" ${props().includes(key)?'checked':''}>${label}</label>`).join('')}<hr style="margin:var(--v-sm) 0">${button('Reset defaults','display-reset','refresh')}</div></div></div><div id="simple-list" class="simple-list"></div><div class="list-foot"><span id="result-count"></span><span>${web?'Cloud records only':'Choose a project to push and publish.'}</span></div>`;paintStatus();paintList();}
function paintStatus(){const el=document.querySelector('#compact-status');if(!el)return;const count=projects.filter(p=>['done','error'].includes(p.phase)).length;const failed=projects.filter(p=>p.phase==='error').length;el.innerHTML=`${checking?spin():icon(failed?'alert':'check')}<span>${checking?`${web?'Loading':'Checking'} ${count}/${projects.length}`:failed?`${failed} unavailable · checked just now`:'Checked just now'}</span>${checking?`<span class="launch-progress"><span style="width:${count/projects.length*100}%"></span></span>`:''}${ib(web?'Refresh cloud records':'Check projects again','check','refresh')}`;const refresh=el.querySelector('button');refresh.disabled=projects.some(p=>['uploading','rechecking'].includes(p.phase));}
function propValue(p,key){if(key==='status')return statusHTML(p);if(key==='path')return `<span class="mono">${esc(p.path)}</span>`;if(p.phase!=='done')return '<span class="muted">—</span>';if(key==='published')return p.publishedAt||'Yesterday, 16:30';if(key==='cloud')return `<span class="mono">${p.cloud}</span>`;if(key==='live')return `<span class="mono">${p.live}</span>`;return esc(p.device);}
function rowAction(p){if(p.phase==='error')return button('Retry','retry:'+p.id,'refresh');if(p.phase!=='done')return button('Checking…','noop','refresh','','disabled');if(web)return button('Details','details:'+p.id,'folder');if(p.kind==='local')return button('Push & publish','upload:'+p.id,'up','primary','data-write');if(p.kind==='same')return button('Details','details:'+p.id,'folder');return button('Review','details:'+p.id,p.kind==='remote'?'down':'diff');}
function paintList(){const list=document.querySelector('#simple-list');if(!list)return;const q=keyword.trim().toLowerCase();const filtered=projects.filter(p=>(p.name+(!web?' '+p.path:'')).toLowerCase().includes(q));const selected=props();list.style.setProperty('--columns',['minmax(190px,1.5fr)',...selected.map(k=>propertyDefs[k][1]),web?'95px':'170px'].join(' '));list.classList.toggle('wide',selected.length>3);list.innerHTML=!filtered.length?`<div class="empty">${icon('folder')}<strong>${projects.length?'No matching projects':'No projects yet'}</strong><p>${projects.length?'Try a different keyword.':web?'Push a project from the desktop app or CLI to see it here.':'Your connected project folders will appear here.'}</p>${projects.length?button('Clear filter','clear-filter','close'):button('Load sample projects','samples','folder')}</div>`:`<div class="simple-head"><span>Project</span>${selected.map(k=>`<span>${propertyDefs[k][0]}</span>`).join('')}<span></span></div>${filtered.map(p=>`<article class="simple-row" data-project="${p.id}"><div class="project-name"><a class="project-link" href="?project=${p.id}&state=ready" data-action="details:${p.id}">${icon('folder')}${esc(p.name)}</a></div>${selected.map(k=>`<div class="prop-cell" data-property="${k}"><span class="prop-label">${propertyDefs[k][0]}</span>${propValue(p,k)}</div>`).join('')}<div class="row-actions">${rowAction(p)}</div></article>`).join('')}`;document.querySelector('#result-count').textContent=`${filtered.length} of ${projects.length} projects`;}
function details(p){currentProject=p.id;displayOpen=false;const u=new URL(location);u.searchParams.set('project',p.id);history.pushState(null,'',u);renderRows();window.scrollTo(0,0);}
function paintDetailBase(){const p=projects.find(p=>p.id===currentProject);if(!p){currentProject=null;renderRows();return;}const s=statusOf(p);document.querySelector('#page-content').innerHTML=`<div class="detail-top"><a href="01.html" data-action="back-list" class="inline">${icon('back')}Projects</a></div><div class="pagehead"><div><h1 class="inline">${icon('folder')}${esc(p.name)}</h1>${!web?`<div class="subtitle mono">${esc(p.path)}</div>`:''}</div>${!web&&p.phase==='done'&&p.kind==='local'?button('Push & publish','upload:'+p.id,'up','primary','data-write'):''}</div><div class="detail-main"><div><section class="panel"><div class="panelhead">${icon(web?'cloud':'computer')}<h2>${web?'Cloud status':'Current status'}</h2></div><div class="panelbody"><p>${statusHTML(p)}</p><p class="muted">${s.detail||''}</p>${p.phase==='done'?`<small>${web?'Loaded':'Checked'} ${p.checked||'just now'}</small>`:''}<div class="detail-actions">${p.phase==='error'?button('Retry check','retry:'+p.id,'refresh'):p.phase==='done'&&!web?(p.kind==='remote'?button('Review & pull','incoming:'+p.id,'down','','data-write'):p.kind==='local'?button('View changes','local:'+p.id,'diff'):p.kind==='conflict'?button('Compare versions','conflict:'+p.id,'diff'):''):''}</div></div></section><section class="panel"><div class="panelhead">${icon('history')}<h2>History</h2><span class="grow"></span></div>${p.phase==='done'?`<div class="history-entry"><span class="mono">${p.cloud}</span><div><b>${esc(p.message)}</b><small>${esc(p.device)} · Today, 09:12</small></div>${button('Compare','history-diff:'+p.id,'diff')}</div><div class="history-entry"><span class="mono">${p.local===p.cloud?'C'+String(Math.max(1,Number(p.cloud.slice(1))-1)).padStart(2,'0'):p.local}</span><div><b>Previous update</b><small>Yesterday, 16:30</small></div>${!web?button('Restore…','restore:'+p.id,'history','','data-write'):''}</div>`:'<div class="panelbody muted">History will be available when cloud records load.</div>'}</section></div><div><section class="panel"><div class="panelhead">${icon('window')}<h2>Publication</h2></div><div class="panelbody"><div class="detail-row"><span>Live</span><b class="mono">${p.phase==='done'?p.live:'Not verified'}</b></div><div class="detail-row"><span>Saved</span><b class="mono">${p.phase==='done'?p.cloud:'Not verified'}</b></div><div class="detail-row"><span>Published</span><span>${p.phase==='done'?(p.publishedAt||'Yesterday, 16:30'):'—'}</span></div>${!web&&p.phase==='done'&&p.cloud!==p.live?`<div class="detail-actions">${button('Publish saved '+p.cloud+'…','publish:'+p.id,'window','','data-write')}</div>`:''}</div></section>${!web&&p.phase==='done'&&p.kind==='local'?`<section class="panel"><div class="panelhead">${icon('cloud')}<h2>Save without publishing</h2></div><div class="panelbody"><p class="muted">Save a checkpoint for another computer. Leave the live site as it is.</p>${button('Push checkpoint only…','checkpoint-only:'+p.id,'up','','data-write')}</div></section>`:''}</div></div>`;}
function goBack(){currentProject=null;const u=new URL(location);u.searchParams.delete('project');history.pushState(null,'',u);renderRows();}
addEventListener('popstate',()=>{currentProject=new URLSearchParams(location.search).get('project');if(document.querySelector('#page-content'))renderRows();});
function round4Click(e){const t=e.target.closest('[data-action]');if(!t)return;const a=t.dataset.action;const [verb,id]=a.split(':');const p=projects.find(p=>p.id===id);if(verb==='details'){e.preventDefault();details(p);return;}if(verb==='back-list'){e.preventDefault();goBack();return;}if(verb==='display'){displayOpen=!displayOpen;document.querySelector('#display-menu').hidden=!displayOpen;t.setAttribute('aria-expanded',String(displayOpen));return;}if(verb==='display-reset'){shownProps=['status','published'];saveProps();renderRows();return;}if(verb==='clear-filter'){keyword='';renderRows();document.querySelector('#keyword').focus();return;}if(verb==='checkpoint-only'){if(web||p.phase!=='done'||p.kind!=='local')return;note='Local update';previousClick({target:{closest:()=>({dataset:{action:'push:'+id}})}});return;}if(verb==='upload'){if(web||p.phase!=='done'||p.kind!=='local')return;dialogProject=id;note='';modal('Push & publish '+p.name,`<p>${p.files} changed files will be uploaded as one complete checkpoint, then published.</p><div class="detail-row"><span>Current live version</span><b>${p.live}</b></div><div class="detail-row"><span>New checkpoint</span><b>C${String(Number(p.cloud.slice(1))+1).padStart(2,'0')}</b></div><label>Update note <span class="muted">(optional)</span><input id="note" placeholder="Describe this update"></label><p class="footnote">Recheck local and remote state before uploading. Other projects stay unchanged.</p>`,button('Cancel','close','close')+button('Push & publish','confirm-upload:'+id,'up','primary','data-write'));return;}if(verb==='confirm-upload'){if(web||p.phase!=='done'||p.kind!=='local')return;document.querySelector('#dialog').close();p.phase='uploading';renderRows();setTimeout(()=>{p.cloud='C'+String(Number(p.cloud.slice(1))+1).padStart(2,'0');p.local=p.cloud;p.live=p.cloud;p.kind='same';p.phase='done';p.checked='just now';p.publishedAt='Just now';p.message=note||'Published local changes';p.device='MacBook';renderRows();toast(p.name+' pushed and published. Other projects unchanged.');},950);return;}previousClick(e);}
function round5Change(e){if(e.target.dataset.prop){const key=e.target.dataset.prop;shownProps=e.target.checked?[...new Set([...props(),key])]:props().filter(k=>k!==key);saveProps();paintList();return;}previousChange(e);}
// History comparison owns only two saved checkpoints of the selected project.
let compareShowing=new URLSearchParams(location.search).get('compare')==='1',historyLayout='unified',activeFile=null;const pointSelections=new Map(),collapsedFiles=new Set();
function projectHistory(p){const n=Number(p.cloud.slice(1));const ids=[n-2,n-1,n].map(x=>'C'+String(Math.max(1,x)).padStart(2,'0'));const first=snapshots(p).old;const css='main {\n  max-width: 960px;\n  padding: 16px;\n}';const v0={'index.html':first,'styles/site.css':css,'legacy.html':'<h1>Previous collection</h1>\n<p>Use the old archive.</p>'};const v1={...v0,'index.html':first.replace('Welcome to the collection.','Welcome to our updated collection.'),'assets/poster.ai':{binary:true,size:'7.2 MB',hash:'8f2d1b…41e0'}};const v2={...v1,'index.html':snapshots(p).new,'styles/site.css':css.replace('960px','1080px').replace('16px','24px'),'robots.txt':'User-agent: *\nAllow: /','assets/poster.ai':{binary:true,size:'8.4 MB',hash:'b97a2e…82c1'}};delete v2['legacy.html'];return {ids,snapshots:{[ids[0]]:v0,[ids[1]]:v1,[ids[2]]:v2},entries:[{id:ids[2],title:p.message,time:'Today, 09:12',device:p.device},{id:ids[1],title:'Updated introduction and artwork',time:'Yesterday, 16:30',device:'MacBook'},{id:ids[0],title:'First complete edition',time:'Sep 18, 11:05',device:'WSL · Studio PC'}]};}
function selectedPoints(p){const h=projectHistory(p);let v=pointSelections.get(p.id);if(!v||!h.ids.includes(v.A)||!h.ids.includes(v.B)){v={A:h.ids[0],B:h.ids[2]};pointSelections.set(p.id,v);}return v;}
function historyPanel(p){const h=projectHistory(p),s=selectedPoints(p);return `<section class="panel history-points"><div class="panelhead">${icon('history')}<h2>History</h2><span class="grow"></span><small>Choose A and B</small></div>${h.entries.map(e=>`<div class="point-row ${s.A===e.id||s.B===e.id?'point-selected':''}"><span class="revision">${e.id}${e.id===p.live?'<br><span class="badge">Live</span>':''}</span><div class="point-copy"><b>${esc(e.title)}</b><small>${esc(e.device)} · ${e.time}</small></div>${button('Browse files','browse-revision:'+e.id,'folder','history-browse',`aria-label="Browse files at ${e.id}"`)}${!web&&e.id===h.ids[1]?ib('Restore previous checkpoint','restore:'+p.id,'history'):''}<span class="ab-slots">${['A','B'].map(side=>`<button data-action="point:${side}:${e.id}" aria-label="Use ${e.id} as ${side}" aria-pressed="${s[side]===e.id}">${side}</button>`).join('')}</span></div>`).join('')}<div class="compare-selection"><span class="choice"><b>A</b><span class="mono">${s.A}</span></span>${ib('Swap A and B','swap-points','refresh')}<span class="choice"><b>B</b><span class="mono">${s.B}</span></span><span class="grow"></span>${button('Compare','open-comparison','diff')}</div></section>`;}
function round5PaintDetail(){document.querySelector('#page-content')?.classList.toggle('compare-page',compareShowing);if(compareShowing){paintComparison();return;}paintDetailBase();const p=projects.find(p=>p.id===currentProject);if(!p||p.phase!=='done')return;const heading=[...document.querySelectorAll('#page-content h2')].find(h=>h.textContent==='History');if(heading)heading.closest('section').outerHTML=historyPanel(p);}
function fileChanges(p){const h=projectHistory(p),s=selectedPoints(p),a=h.snapshots[s.A],b=h.snapshots[s.B];return [...new Set([...Object.keys(a),...Object.keys(b)])].filter(k=>JSON.stringify(a[k])!==JSON.stringify(b[k])).map(path=>{const left=a[path],right=b[path],binary=typeof left==='object'||typeof right==='object';const rows=binary?[]:diffRows(left||'',right||'');return {path,left,right,binary,kind:left===undefined?'A':right===undefined?'D':'M',rows,added:rows.filter(x=>x.k==='added').length,removed:rows.filter(x=>x.k==='removed').length};});}
function markedRows(rows){const marked=new Map();for(let i=0;i<rows.length;){if(rows[i].k!=='removed'){i++;continue;}const start=i;while(rows[i]?.k==='removed')i++;const added=i;while(rows[i]?.k==='added')i++;for(let k=0;k<Math.min(added-start,i-added);k++){const l=rows[start+k],r=rows[added+k];let pre=0,suf=0;while(pre<l.v.length&&pre<r.v.length&&l.v[pre]===r.v[pre])pre++;while(suf<l.v.length-pre&&suf<r.v.length-pre&&l.v[l.v.length-1-suf]===r.v[r.v.length-1-suf])suf++;for(const [line,tag] of [[l,'del'],[r,'ins']])marked.set(line,esc(line.v.slice(0,pre))+`<${tag}>`+esc(line.v.slice(pre,line.v.length-suf))+`</${tag}>`+esc(suf?line.v.slice(-suf):''));}}return marked;}
function fileTable(f,s){if(f.binary)return `<div class="binary-sides">${[[s.A,f.left],[s.B,f.right]].map(([id,v])=>`<div class="binary-side"><span class="label">${id}</span><p>${icon('image')} <b>${v?'Binary file':'File not present'}</b></p>${v?`<p>${esc(v.size)}<br><span class="mono">SHA-256 ${esc(v.hash)}</span></p>`:''}</div>`).join('')}</div><div class="diff-summary">Binary content is not shown as a text diff.</div>`;const rows=f.rows,marks=markedRows(rows),code=o=>o?(marks.get(o)||esc(o.v)):'';if(historyLayout==='split'&&!smallScreen.matches){let paired=[];for(let i=0;i<rows.length;){if(rows[i].k==='same'){paired.push([rows[i],rows[i]]);i++;continue;}const left=[],right=[];while(rows[i]?.k==='removed')left.push(rows[i++]);while(rows[i]?.k==='added')right.push(rows[i++]);for(let k=0;k<Math.max(left.length,right.length);k++)paired.push([left[k],right[k]]);}return `<div class="diff-labels"><span>A · ${s.A}</span><span>B · ${s.B}</span></div><div class="code-scroll"><table class="diff-table" aria-label="Split diff for ${f.path}"><colgroup><col style="width:32px"><col style="width:20px"><col><col style="width:32px"><col style="width:20px"><col></colgroup><tbody>${paired.map(([l,r])=>`<tr><td class="ln">${l?.a||''}</td><td class="sign ${l?.k||''}">${l?.k==='removed'?'−':''}</td><td class="code middle ${l?.k||''}">${code(l)}</td><td class="ln">${r?.b||''}</td><td class="sign ${r?.k||''}">${r?.k==='added'?'+':''}</td><td class="code ${r?.k||''}">${code(r)}</td></tr>`).join('')}</tbody></table></div>`;}return `<div class="hunk">A · ${s.A} → B · ${s.B}</div><div class="code-scroll"><table class="diff-table" aria-label="Unified diff for ${f.path}"><colgroup><col style="width:32px"><col style="width:32px"><col style="width:20px"><col></colgroup><tbody>${rows.map(o=>`<tr class="${o.k}"><td class="ln">${o.a}</td><td class="ln">${o.b}</td><td class="sign">${o.k==='added'?'+':o.k==='removed'?'−':''}</td><td class="code">${code(o)}</td></tr>`).join('')}</tbody></table></div>`;}
function paintComparison(){const p=projects.find(p=>p.id===currentProject);if(!p)return;const s=selectedPoints(p),files=fileChanges(p),added=files.reduce((n,f)=>n+f.added,0),removed=files.reduce((n,f)=>n+f.removed,0);if(!files.some(f=>f.path===activeFile))activeFile=files[0]?.path;document.querySelector('#page-content').innerHTML=`<div class="detail-top"><a href="?project=${p.id}" data-action="history-back" class="inline">${icon('back')}${esc(p.name)} / History</a></div><div class="pagehead"><div><h1>Compare checkpoints</h1><div class="subtitle">${esc(p.name)} · A <b class="mono">${s.A}</b> → B <b class="mono">${s.B}</b></div></div>${button('Change selection','history-back','history')}</div><div class="compare-toolbar"><span class="inline">${icon('diff')}<b>${files.length} changed files</b></span><span class="mono"><span class="success">+${added}</span> <span class="danger">−${removed}</span></span><small>text lines${files.some(f=>f.binary)?' · 1 binary file':''}</small><span class="grow"></span>${ib('Swap A and B','swap-comparison','refresh')}${ib('Expand all files','files-expand','down')}${ib('Collapse all files','files-collapse','up')}<span class="separator"></span>${button('Unified','history-layout:unified','unified','',`aria-pressed="${historyLayout==='unified'||smallScreen.matches}"`)}${button('Split','history-layout:split','split','split-control',`aria-pressed="${historyLayout==='split'&&!smallScreen.matches}"`)}</div>${!files.length?`<div class="comparison-empty">${icon('check')}<h2>No file changes</h2><p>${s.A} and ${s.B} contain the same files.</p></div>`:`<div class="comparison-layout"><aside class="changed-files" aria-label="Changed files"><div class="panelhead"><h2>Files changed</h2><span class="grow"></span><span class="mono">${files.length}</span></div>${files.map((f,i)=>`<button class="file-link" data-action="jump-file:${i}" aria-current="${f.path===activeFile}">${icon(f.binary?'image':'file')}<span class="file-path">${esc(f.path)}</span><span class="file-mark ${f.kind==='A'?'success':f.kind==='D'?'danger':'warn'}">${f.kind}</span><span class="file-count">${f.binary?'binary':`+${f.added} −${f.removed}`}</span></button>`).join('')}</aside><div class="file-diffs">${files.map((f,i)=>`<details class="file-diff" id="file-${i}" data-path="${esc(f.path)}" ${collapsedFiles.has(f.path)?'':'open'}><summary class="file-heading"><span class="chevron">›</span>${icon(f.binary?'image':'file')}<span class="file-path">${esc(f.path)}</span><span class="file-mark ${f.kind==='A'?'success':f.kind==='D'?'danger':'warn'}">${f.kind}</span><span class="file-totals">${f.binary?'Binary':`<span class="success">+${f.added}</span> <span class="danger">−${f.removed}</span>`}</span></summary>${fileTable(f,s)}</details>`).join('')}</div></div>`}<p class="footnote">Read-only comparison of saved checkpoints. No local files or publication are changed.</p>`;document.querySelectorAll('.file-diff').forEach(el=>el.addEventListener('toggle',()=>{if(el.open)collapsedFiles.delete(el.dataset.path);else collapsedFiles.add(el.dataset.path)}));}
function comparisonRoute(open){compareShowing=open;const u=new URL(location);if(open)u.searchParams.set('compare','1');else u.searchParams.delete('compare');u.searchParams.set('project',currentProject);history.pushState(null,'',u);renderRows();window.scrollTo(0,0);}
function round5Click(e){const t=e.target.closest('[data-action]');if(!t)return;const [v,x,y]=t.dataset.action.split(':');const p=projects.find(p=>p.id===currentProject);if(v==='point'){selectedPoints(p)[x]=y;paintDetail();return;}if(v==='swap-points'||v==='swap-comparison'){const s=selectedPoints(p);[s.A,s.B]=[s.B,s.A];collapsedFiles.clear();paintDetail();return;}if(v==='open-comparison'){collapsedFiles.clear();comparisonRoute(true);return;}if(v==='history-back'){e.preventDefault();comparisonRoute(false);return;}if(v==='history-layout'){historyLayout=x;paintComparison();return;}if(v==='files-expand'||v==='files-collapse'){document.querySelectorAll('.file-diff').forEach(el=>{el.open=v==='files-expand';if(el.open)collapsedFiles.delete(el.dataset.path);else collapsedFiles.add(el.dataset.path)});return;}if(v==='jump-file'){const el=document.querySelector('#file-'+x);activeFile=el.dataset.path;el.open=true;collapsedFiles.delete(activeFile);document.querySelectorAll('.file-link').forEach(b=>b.setAttribute('aria-current',String(b===t)));el.scrollIntoView({behavior:'instant',block:'start'});return;}if(v==='details'||v==='back-list')compareShowing=false;round4Click(e);}
smallScreen.addEventListener('change',()=>{if(compareShowing&&currentProject)paintComparison()});addEventListener('popstate',()=>{compareShowing=new URLSearchParams(location.search).get('compare')==='1';if(currentProject)paintDetail();});
// Current files are read-only inspection, separate from historical comparisons.
let historicalRevision=new URLSearchParams(location.search).get('revision');let showFiles=new URLSearchParams(location.search).get('view')==='files';let fileSource=new URLSearchParams(location.search).get('source')||null;let selectedPath=new URLSearchParams(location.search).get('file')||'index.html';let fileKeyword='';const closedFolders=new Set();
function allowedSource(){if(historicalRevision)return 'checkpoint';if(!['local','saved','live'].includes(fileSource)||web&&fileSource==='local')fileSource=web?'saved':'local';return fileSource;}
function sourceLabel(p){if(historicalRevision)return 'Checkpoint · '+historicalRevision;return allowedSource()==='local'?'Current local files':fileSource==='live'?'Published · '+p.live:'Latest saved · '+p.cloud;}
function fileCatalog(p){const source=allowedSource(),h=projectHistory(p);if(source!=='local'&&p.phase!=='done')return null;const rev=historicalRevision||(source==='local'?p.local:source==='live'?p.live:p.cloud);if(historicalRevision&&!h.snapshots[historicalRevision])return null;const originals=structuredClone(h.snapshots[rev]||h.snapshots[h.ids[2]]);originals['README.md']='# '+p.name+'\n\nA small, independent static site.\n\n## Contents\n\n- index.html — site entry point\n- assets/ — images and artwork\n- styles/ — site styles';originals['assets/exhibition.svg']={image:true,size:883,width:960,height:540,mime:'image/svg+xml',url:'preview-sample.svg'};originals['assets/icons/site.svg']={image:true,size:883,width:960,height:540,mime:'image/svg+xml',url:'preview-sample.svg'};originals['scripts/site.js']='document.querySelectorAll("nav a").forEach((link) => {\n  link.addEventListener("click", () => {\n    console.log("Navigation selected");\n  });\n});';originals['scripts/site.js.map']={large:true,size:2400000,mime:'application/json'};if(source==='local'&&['local','conflict'].includes(p.kind)){originals['index.html']=originals['index.html'].replace('Explore the latest collection.','A local update — not uploaded yet.');originals['notes/draft.txt']='Local draft for '+p.name+'.\nThis file has not been pushed to the cloud.\n';}return Object.fromEntries(Object.entries(originals).map(([path,v])=>[path,typeof v==='string'?{kind:'text',text:v,size:new TextEncoder().encode(v).length,mime:path.endsWith('.html')?'text/html':path.endsWith('.css')?'text/css':path.endsWith('.js')?'text/javascript':'text/plain'}:v.image?{...v,kind:'image'}:v.large?{...v,kind:'large'}:{...v,kind:'binary',size:Number.parseFloat(v.size)*1000000,mime:'application/postscript'}]));}
const byteLabel=n=>n>=1000000?(n/1000000).toFixed(1)+' MB':n>=1000?(n/1000).toFixed(1)+' KB':n+' B';
function makeTree(catalog){const root={path:'',name:'',folder:true,children:{}};for(const path of [...Object.keys(catalog),'empty/']){const parts=path.replace(/\/$/,'').split('/');let parent=root;parts.forEach((name,i)=>{const folder=i<parts.length-1||path.endsWith('/'),key=parts.slice(0,i+1).join('/')+(folder?'/':'');parent.children[name]??={path:key,name,folder,children:{}};parent=parent.children[name]});}return root;}
function treeHasMatch(n){if(n.path.toLowerCase().includes(fileKeyword.toLowerCase()))return true;return Object.values(n.children).some(treeHasMatch);}
function treeHTML(root){return `<ul class="tree-list">${Object.values(root.children).sort((a,b)=>Number(b.folder)-Number(a.folder)||a.name.localeCompare(b.name)).filter(n=>!fileKeyword||treeHasMatch(n)).map(n=>`<li><div class="tree-row" aria-current="${selectedPath===n.path}">${n.folder?`<button class="twisty" data-action="folder-toggle:${n.path}" aria-label="${closedFolders.has(n.path)&&!fileKeyword?'Expand':'Collapse'} ${n.name}" aria-expanded="${!closedFolders.has(n.path)||!!fileKeyword}">${closedFolders.has(n.path)&&!fileKeyword?'›':'⌄'}</button>`:''}<button class="tree-name" data-action="inspect-file:${n.path}">${icon(n.folder?'folder':n.name.endsWith('.svg')||n.name.endsWith('.ai')?'image':'file')}<span class="name">${esc(n.name)}${n.folder?'/':''}</span></button></div>${n.folder&&(!closedFolders.has(n.path)||fileKeyword)?treeHTML(n):''}</li>`).join('')}</ul>`;}
function filesAndHistoryDetail(){document.querySelector('#page-content')?.classList.toggle('files-page',showFiles);if(showFiles){paintFiles();return;}round5PaintDetail();if(compareShowing)return;const p=projects.find(p=>p.id===currentProject);if(!p)return;const head=document.querySelector('#page-content .pagehead');if(head&&!head.querySelector('[data-action="open-files"]')){const original=[...head.children].filter(x=>x.tagName==='BUTTON');const actions=document.createElement('div');actions.className='actions';actions.innerHTML=button('Browse files','open-files','folder');original.forEach(x=>actions.append(x));head.append(actions);}}
function paintFilesBase(){const p=projects.find(p=>p.id===currentProject);if(!p)return;document.querySelector('#page-content').classList.remove('compare-page');const source=allowedSource();document.querySelector('#page-content').innerHTML=`<div class="detail-top"><a href="?project=${p.id}" data-action="files-back" class="inline">${icon('back')}${esc(p.name)}</a></div><div class="pagehead"><div><h1>Files</h1><div class="subtitle">${esc(p.name)} · read-only file viewer</div></div><span class="source-chip inline">${icon(source==='local'?'computer':source==='live'?'window':'cloud')}<span id="source-label">${sourceLabel(p)}</span></span></div><div class="files-toolbar"><label class="inline">Source <select id="file-source" aria-label="File source">${!web?'<option value="local">Current local files</option>':''}<option value="saved">Latest saved checkpoint · ${p.cloud}</option><option value="live">Published checkpoint · ${p.live}</option></select></label><span class="grow"></span><small>${source==='local'?'Files on this computer. Viewing does not upload them.':'A saved snapshot. Viewing does not change publication.'}</small></div><div class="files-layout"><nav class="folder-pane" aria-label="Project files"><div class="folder-tools"><input id="file-filter" aria-label="Filter files" placeholder="Filter files…" value="${esc(fileKeyword)}"><span class="label">Files</span>${ib('Expand all folders','folders-expand','down')}${ib('Collapse all folders','folders-collapse','up')}</div><div class="tree-scroll" id="file-tree"></div></nav><section class="file-content" aria-label="File contents" id="file-content"></section><aside class="file-inspector" aria-label="File details" id="file-details"></aside></div>`;document.querySelector('#file-source').value=source;paintFilePanels();}
function paintFilePanels(){requestAnimationFrame(measureFileTree);const p=projects.find(p=>p.id===currentProject),catalog=fileCatalog(p);if(!catalog){document.querySelector('#file-tree').innerHTML='<div class="tree-empty">Cloud file list unavailable.</div>';document.querySelector('#file-content').innerHTML=`<div class="file-state">${icon('alert')}<h2>Couldn’t load cloud files</h2><p>Check this project again before viewing this snapshot.</p></div>`;document.querySelector('#file-details').innerHTML='<div class="panelhead"><h2>Details</h2></div><div class="panelbody muted">No verified cloud file selected.</div>';return;}const folders=new Set(['empty/']);Object.keys(catalog).forEach(path=>{const parts=path.split('/');for(let i=1;i<parts.length;i++)folders.add(parts.slice(0,i).join('/')+'/')});if(selectedPath&&!catalog[selectedPath]&&!folders.has(selectedPath))selectedPath='';const tree=makeTree(catalog);document.querySelector('#file-tree').innerHTML=`<div class="tree-row" aria-current="${selectedPath===''}"><span class="spacer"></span><button class="tree-name" data-action="inspect-file:">${icon('folder')}<span class="name">${esc(p.name)}/</span></button></div>${!fileKeyword||Object.values(tree.children).some(treeHasMatch)?treeHTML(tree):'<div class="tree-empty">No matching files.</div>'}`;
const file=catalog[selectedPath],isFolder=!file;const paths=Object.keys(catalog).filter(path=>path.startsWith(selectedPath));const size=isFolder?paths.reduce((total,path)=>total+catalog[path].size,0):file.size;let preview='';
if(isFolder){preview=`<div class="folder-summary"><h2 class="inline">${icon('folder')}${esc(selectedPath||p.name+'/')}</h2><p class="muted">${paths.length} files · ${byteLabel(size)}</p>${paths.length?paths.map(path=>`<div class="folder-child">${icon(catalog[path].kind==='image'?'image':'file')}<span class="grow mono">${esc(path.slice(selectedPath.length))}</span><small>${byteLabel(catalog[path].size)}</small>${button('View','inspect-file:'+path,'file')}</div>`).join(''):'<div class="file-state"><h2>Empty folder</h2><p>No files in this folder.</p></div>'}</div>`;}else if(file.kind==='text'){preview=`<div class="file-code-wrap"><table class="file-code" aria-label="Contents of ${esc(selectedPath)}"><tbody>${file.text.split('\n').map((line,i)=>`<tr><td class="ln">${i+1}</td><td class="source-text">${esc(line)||' '}</td></tr>`).join('')}</tbody></table></div>`;}else if(file.kind==='image'){preview=`<div class="image-stage"><img src="${file.url}" width="${file.width}" height="${file.height}" alt="Fictional exhibition artwork"></div><div class="diff-summary">${file.width} × ${file.height} · ${file.mime}</div>`;}else{preview=`<div class="file-state">${icon(file.kind==='binary'?'image':'file')}<h2>${file.kind==='binary'?'No preview for this file type':'File too large to preview'}</h2><p>${file.kind==='binary'?'Binary artwork cannot be displayed as text.':'This 2.4 MB file exceeds the prototype’s text-preview limit.'}</p><p class="mono">${esc(selectedPath)}</p><p>File metadata remains available in Details.</p></div>`;}
document.querySelector('#file-content').innerHTML=`<div class="panelhead">${icon(isFolder?'folder':file.kind==='image'?'image':'file')}<h2 class="selected-path">${esc(selectedPath||p.name+'/')}</h2><span class="grow"></span><span class="badge">Read only</span></div>${preview}`;const props=[['Path',selectedPath||'/'],['Type',isFolder?'Folder':file.mime],['Size',byteLabel(size)],['Source',sourceLabel(p)],...(isFolder?[['Files',String(paths.length)]]:file.kind==='image'?[['Dimensions',file.width+' × '+file.height]]:file.kind==='text'?[['Lines',String(file.text.split('\n').length)]]:[]),['Updated',historicalRevision?(projectHistory(p).entries.find(e=>e.id===historicalRevision)?.time||'Unknown')+' · checkpoint snapshot':allowedSource()==='local'?'Today, 10:40 · this computer':'Today, 09:12 · checkpoint snapshot']];document.querySelector('#file-details').innerHTML=`<div class="panelhead">${icon('file')}<h2>Details</h2></div><div class="panelbody"><dl>${props.map(([label,value])=>`<div class="file-property"><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></div>`;}
function fileRoute(open){showFiles=open;compareShowing=false;const u=new URL(location);u.searchParams.delete('compare');u.searchParams.set('project',currentProject);if(open)u.searchParams.set('view','files');else{u.searchParams.delete('view');u.searchParams.delete('source');u.searchParams.delete('file');u.searchParams.delete('revision');}history.pushState(null,'',u);renderRows();window.scrollTo(0,0);}
function currentFilesClick(e){const t=e.target.closest('[data-action]');if(!t)return;const a=t.dataset.action,v=a.split(':')[0],value=a.slice(v.length+1);if(v==='open-files'){fileRoute(true);return;}if(v==='files-back'){e.preventDefault();fileRoute(false);return;}if(v==='inspect-file'){selectedPath=value;const u=new URL(location);u.searchParams.set('file',value);u.searchParams.set('source',allowedSource());history.replaceState(null,'',u);paintFilePanels();return;}if(v==='folder-toggle'){if(closedFolders.has(value))closedFolders.delete(value);else closedFolders.add(value);paintFilePanels();return;}if(v==='folders-expand'||v==='folders-collapse'){closedFolders.clear();if(v==='folders-collapse'){const c=fileCatalog(projects.find(p=>p.id===currentProject));if(c)Object.keys(c).forEach(path=>{const parts=path.split('/');for(let i=1;i<parts.length;i++)closedFolders.add(parts.slice(0,i).join('/')+'/')});closedFolders.add('empty/');}paintFilePanels();return;}if(['details','back-list','open-comparison'].includes(v))showFiles=false;round5Click(e);}
function change(e){if(e.target.id==='file-source'){fileSource=e.target.value;const u=new URL(location);u.searchParams.set('source',fileSource);history.replaceState(null,'',u);paintFiles();return;}round5Change(e);}
document.addEventListener('input',e=>{if(e.target.id==='file-filter'){fileKeyword=e.target.value;paintFilePanels();}});addEventListener('popstate',()=>{showFiles=new URLSearchParams(location.search).get('view')==='files';if(currentProject)paintDetail();});

function measureFileTree(){const root=document.querySelector('#file-tree');if(!root)return;root.querySelectorAll('.tree-list').forEach(list=>{const last=list.lastElementChild;if(!last){list.style.setProperty('--tree-trunk-end','0px');return;}const row=last.querySelector(':scope > .tree-row');const box=list.getBoundingClientRect();if(row){const rb=row.getBoundingClientRect();list.style.setProperty('--tree-trunk-end',(rb.top-box.top+rb.height/2)+'px');}list.querySelectorAll(':scope > li').forEach(item=>{const row=item.querySelector(':scope > .tree-row');if(row)item.style.setProperty('--tree-row-center',(row.getBoundingClientRect().height/2)+'px');});});}
new ResizeObserver(measureFileTree).observe(document.documentElement);

function paintFiles(){paintFilesBase();if(!historicalRevision)return;const p=projects.find(p=>p.id===currentProject);const entry=projectHistory(p).entries.find(e=>e.id===historicalRevision);const toolbar=document.querySelector('.files-toolbar');if(toolbar)toolbar.innerHTML=`<span class="inline">${icon('history')}<b class="mono">${esc(historicalRevision)}</b><span>${entry?esc(entry.title):'Checkpoint unavailable'}</span></span><span class="grow"></span><span class="badge">Historical snapshot · read only</span>`;const back=document.querySelector('[data-action="files-back"]');if(back)back.innerHTML=icon('back')+esc(p.name)+' / History';document.querySelector('.pagehead h1').textContent='Files at '+historicalRevision;if(!entry){document.querySelector('#file-content').innerHTML='<div class="file-state">'+icon('alert')+'<h2>Checkpoint unavailable</h2><p>This checkpoint was not found. No other version has been substituted.</p></div>';}}
function historyFilesClick(e){const t=e.target.closest('[data-action]');if(!t)return;const a=t.dataset.action;if(a.startsWith('browse-revision:')){historicalRevision=a.slice('browse-revision:'.length);showFiles=true;compareShowing=false;selectedPath='index.html';fileKeyword='';closedFolders.clear();const u=new URL(location);u.searchParams.set('project',currentProject);u.searchParams.set('view','files');u.searchParams.set('revision',historicalRevision);u.searchParams.delete('compare');u.searchParams.delete('source');u.searchParams.delete('file');history.pushState(null,'',u);renderRows();window.scrollTo(0,0);return;}if(a==='files-back'){historicalRevision=null;fileSource=web?'saved':'local';}if(a==='open-files'){historicalRevision=null;const u=new URL(location);u.searchParams.delete('revision');history.replaceState(null,'',u);}currentFilesClick(e);}
addEventListener('popstate',()=>{historicalRevision=new URLSearchParams(location.search).get('revision');if(showFiles&&currentProject)paintFiles();});
// Local and incoming review use dedicated project pages, never diff dialogs.
let reviewMode=new URLSearchParams(location.search).get('review')||null,reviewChoice=null,reviewBusy=false;
let mergeResolved=false,mergeText='',mergeReviewed=false;

function openDiff(p,mode){dialogProject=p.id;currentProject=p.id;diffDirection=mode;diffFile='index.html';note='';reviewChoice=null;showFiles=false;compareShowing=false;historicalRevision=null;if(mode==='history'){reviewMode=null;compareShowing=true;const u=new URL(location);u.searchParams.set('project',p.id);u.searchParams.set('compare','1');u.searchParams.delete('review');history.pushState(null,'',u);renderRows();return;}reviewMode=mode;const u=new URL(location);u.searchParams.set('project',p.id);u.searchParams.set('review',mode);for(const key of ['view','compare','revision','source','file'])u.searchParams.delete(key);history.pushState(null,'',u);document.querySelector('#dialog')?.close();renderRows();window.scrollTo(0,0);}
function paintDetail(){document.querySelector('#page-content')?.classList.toggle('review-page',!!reviewMode);if(reviewMode){paintReviewPage();return;}filesAndHistoryDetail();}
function reviewFiles(p){return ['index.html','styles/site.css',...(reviewMode==='local'?['assets/poster.ai']:[])].map(path=>{if(path.endsWith('.ai'))return {path,kind:'A',binary:true,added:0,removed:0};let {old:left,new:right}=snapshots(p);if(path.endsWith('.css')){left='main {\n  max-width: 960px;\n  padding: 16px;\n}';right='main {\n  max-width: 1080px;\n  padding: 24px;\n}';}if(reviewMode==='conflict')left=left.replace('Welcome to the collection.','An exhibition of new ideas.');const rows=diffRows(left,right);return {path,kind:'M',binary:false,added:rows.filter(r=>r.k==='added').length,removed:rows.filter(r=>r.k==='removed').length};});}
function paintReviewPage(){const p=projects.find(p=>p.id===currentProject);if(!p)return;document.querySelector('#page-content').classList.remove('files-page','compare-page');if(web){document.querySelector('#page-content').innerHTML=`<div class="detail-top"><a href="?project=${p.id}" data-action="review-back">${icon('back')}Project detail</a></div><div class="panel panelbody"><h1>Local review is available in the desktop app</h1><p>The web app can compare saved checkpoints from History.</p></div>`;return;}dialogProject=p.id;diffDirection=reviewMode;const files=reviewFiles(p);if(!files.some(f=>f.path===diffFile))diffFile=files[0].path;const incoming=reviewMode==='incoming',conflict=reviewMode==='conflict';const eligible=p.phase==='done'&&p.kind===(incoming?'remote':conflict?'conflict':'local')&&!reviewBusy;const title=incoming?'Review incoming changes':conflict?'Compare local and remote':'Review local changes';let actions=incoming?button(reviewBusy?'Rechecking & pulling…':'Pull '+files.length+' files','review-pull','down','primary',`data-write ${eligible?'':'disabled'}`):conflict?button('Use local version…','review-choice:local','up','',`data-write ${eligible?'':'disabled'}`)+button('Use remote version…','review-choice:remote','down','',`data-write ${eligible?'':'disabled'}`)+button('Smart merge…','review-choice:smart','diff','primary',`data-write ${eligible?'':'disabled'}`):button('Push checkpoint…','push:'+p.id,'up','primary',`data-write ${eligible?'':'disabled'}`);
document.querySelector('#page-content').innerHTML=`<div class="detail-top"><a href="?project=${p.id}" class="inline" data-action="review-back">${icon('back')}${esc(p.name)}</a></div><div class="pagehead"><div><h1>${title}</h1><div class="subtitle">${esc(p.name)} · ${incoming?`This folder ${p.local} → remote ${p.cloud}`:conflict?`Last common checkpoint ${p.local} · Remote ${p.cloud}`:`Cloud ${p.cloud} → local edits`}</div></div></div>${conflict?'<div class="review-context warning">'+icon('alert')+' Both versions changed. Choose a version or merge changes from the last common checkpoint.</div>':''}<div class="review-toolbar"><span class="inline">${icon('diff')}<b>${files.length} changed files</b></span><span class="grow"></span>${ib('Unified diff','layout:unified','unified',diffLayout==='unified'||smallScreen.matches)}${ib('Split diff','layout:split','split',diffLayout==='split'&&!smallScreen.matches,'split-toggle')}</div><div class="review-layout"><nav class="review-file-list" aria-label="Changed files"><div class="panelhead"><h2>Changed files</h2></div>${files.map(f=>`<button class="review-file" data-action="review-file:${f.path}" aria-pressed="${diffFile===f.path}">${icon(f.binary?'image':'file')}<span class="review-file-name">${esc(f.path)}</span><span class="file-mark ${f.kind==='A'?'success':'warn'}">${f.kind}</span><span class="mono">${f.binary?'Binary':`+${f.added} −${f.removed}`}</span></button>`).join('')}</nav><section class="review-diff" aria-label="Selected file diff"><div id="diff-pane"></div></section></div><div class="review-actionbar">${reviewMode==='local'?`<label class="note">Checkpoint note<input id="note" value="${esc(note)}" placeholder="Describe this update"></label>`:`<small>${reviewBusy?'Rechecking local and remote state before applying this project.':incoming?'Only this local folder will be updated. Published site stays unchanged.':'A recovery copy or checkpoint is preserved before replacement.'}</small>`}<span class="grow"></span><div class="actions">${actions}</div></div>${!eligible&&!reviewBusy?'<p class="footnote">This action is unavailable until the project has a verified matching state. Return to project detail to check it.</p>':''}${reviewChoice==='smart'?smartMergePanel(p,eligible):reviewChoice?`<section class="inline-resolution" aria-label="Confirm replacement"><h2>${reviewChoice==='local'?'Replace the remote checkpoint with local files?':'Replace this local folder with remote files?'}</h2><p>${reviewChoice==='local'?'Keep the current cloud checkpoint in history, then save the reviewed local files.':'Preserve the current local files in a recovery copy, then apply the reviewed remote checkpoint.'}</p><p class="muted">Recheck both versions first. Publication is unchanged.</p><div class="actions">${button('Cancel','review-cancel','close')}${button(reviewBusy?'Rechecking…':'Preserve and replace','review-apply','history','primary',`data-write ${eligible?'':'disabled'}`)}</div></section>`:''}`;paintDiff();}
function leaveReview(){reviewMode=null;reviewChoice=null;const u=new URL(location);u.searchParams.delete('review');history.pushState(null,'',u);renderRows();window.scrollTo(0,0);}
async function click(e){const t=e.target.closest('[data-action]');if(!t)return;const a=t.dataset.action;if(a==='review-back'){e.preventDefault();if(!reviewBusy)leaveReview();return;}if(a.startsWith('review-file:')){diffFile=a.slice('review-file:'.length);paintReviewPage();return;}if(a==='review-pull'){const p=projects.find(p=>p.id===currentProject);if(web||reviewBusy||p.phase!=='done'||p.kind!=='remote')return;reviewBusy=true;paintReviewPage();await pull([p.id]);reviewBusy=false;leaveReview();return;}if(a.startsWith('review-choice:')){if(web||reviewBusy)return;reviewChoice=a.slice('review-choice:'.length);if(reviewChoice==='smart'){mergeResolved=false;mergeText='';mergeReviewed=false;}paintReviewPage();document.querySelector('.inline-resolution')?.scrollIntoView({block:'nearest'});return;}if(a.startsWith('merge-')){await smartMergeAction(a);return;}if(a==='review-cancel'){reviewChoice=null;paintReviewPage();return;}if(a==='review-apply'){const p=projects.find(p=>p.id===currentProject);if(web||reviewBusy||p.phase!=='done'||p.kind!=='conflict')return;const choice=reviewChoice;reviewBusy=true;paintReviewPage();await delay(900);if(choice==='local')p.cloud='C'+String(Number(p.cloud.slice(1))+1).padStart(2,'0');p.local=p.cloud;p.kind='same';p.checked='just now';reviewBusy=false;leaveReview();toast('Replacement simulated for '+p.name+'. Recovery retained; publication unchanged.');return;}if(a==='details'||a==='back-list'||a==='open-files'||a==='open-comparison')reviewMode=null;historyFilesClick(e);}
smallScreen.addEventListener('change',()=>{if(reviewMode&&currentProject)paintReviewPage();});addEventListener('popstate',()=>{reviewMode=new URLSearchParams(location.search).get('review');if(currentProject)paintDetail();});

// Smart merge is a simulated three-way preview; production uses the native merge engine.
function smartMergePanel(p,eligible){return `<section class="inline-resolution smart-merge" aria-label="Smart merge preview"><h2>Smart merge</h2><p>Base ${esc(p.local)} · Local files · Remote ${esc(p.cloud)}</p><p>1 file merged automatically · ${mergeResolved?'0 unresolved conflicts':'1 conflict needs your choice'}</p><div class="merge-auto">${icon('check')} styles/site.css — independent edits combined</div><h3>index.html · overlapping text changes</h3><div class="merge-sources"><div><b>Base</b><pre>Welcome to the collection.</pre></div><div><b>Local</b><pre>An exhibition of new ideas.</pre></div><div><b>Remote</b><pre>Explore the latest collection.</pre></div></div><div class="actions">${button('Use local text','merge-local','computer')}${button('Use remote text','merge-remote','cloud')}${button('Combine both','merge-both','diff')}</div><label class="merge-editor">Merged text<textarea id="merge-text" rows="3" placeholder="Choose a version or write the merged text…">${esc(mergeText)}</textarea></label><div class="actions">${button('Mark resolved','merge-resolve','check','',`data-write ${mergeText.trim()?'':'disabled'}`)}</div><p role="status">${mergeResolved?'All conflicts resolved. Review the combined result before applying.':'Unresolved changes block Apply. No files have changed.'}</p><label class="merge-reviewed"><input id="merge-reviewed" type="checkbox" ${mergeReviewed?'checked':''} ${mergeResolved?'':'disabled'}> I reviewed the merged result</label><p class="muted">Recheck both versions and preserve a recovery copy before applying locally. Push and publication remain separate.</p><div class="actions">${button('Cancel','review-cancel','close')}${button(reviewBusy?'Rechecking…':'Apply merged files','merge-apply','check','primary',`data-write ${eligible&&mergeResolved&&mergeReviewed?'':'disabled'}`)}</div></section>`;}
async function smartMergeAction(a){const p=projects.find(p=>p.id===currentProject);if(web||reviewBusy||reviewChoice!=='smart'||p?.phase!=='done'||p.kind!=='conflict')return;if(['merge-local','merge-remote','merge-both'].includes(a)){mergeText=a==='merge-local'?'An exhibition of new ideas.':a==='merge-remote'?'Explore the latest collection.':'An exhibition of new ideas. Explore the latest collection.';mergeResolved=false;mergeReviewed=false;}else if(a==='merge-resolve'){if(!mergeText.trim())return;mergeResolved=true;mergeReviewed=false;}else if(a==='merge-apply'){if(!mergeResolved||!mergeReviewed)return;reviewBusy=true;paintReviewPage();await delay(900);p.local=p.cloud;p.kind='local';p.files=2;p.checked='just now';reviewBusy=false;leaveReview();toast('Smart merge simulated. Merged files are local changes; recovery retained. Push and publish when ready.');return;}paintReviewPage();}
addEventListener('input',e=>{if(e.target.id!=='merge-text')return;mergeText=e.target.value;mergeResolved=false;mergeReviewed=false;document.querySelector('[data-action="merge-resolve"]').disabled=!mergeText.trim();document.querySelector('[data-action="merge-apply"]').disabled=true;const reviewed=document.querySelector('#merge-reviewed');reviewed.checked=false;reviewed.disabled=true;document.querySelector('.smart-merge [role="status"]').textContent='Unresolved changes block Apply. No files have changed.';});
addEventListener('change',e=>{if(e.target.id==='merge-reviewed'){mergeReviewed=e.target.checked;document.querySelector('[data-action="merge-apply"]').disabled=!(mergeResolved&&mergeReviewed);}});
